def is_tree_balanced(root):
    def dfs(node):
        if not node:
            return 0
        left_height = dfs(node.left)
        right_height = dfs(node.right)
        if abs(left_height - right_height) > 1:
            raise ValueError("Tree is not balanced")
        return max(left_height, right_height) + 1
    try:
        dfs(root)
        return True
    except ValueError:
        return False

