def num_comm_div(a, b):
    # Find the minimum of the two numbers
    min_num = min(a, b)

    # Initialize a list to store the common divisors
    common_divisors = []

    # Iterate through numbers from 1 to the minimum of the two numbers
    for i in range(1, min_num + 1):
        if a % i == 0 and b % i == 0:
            common_divisors.append(i)

    # Return the number of common divisors
    return len(common_divisors)

